function say(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');toastTimer=2.6}
function rr(x,y,w,h,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function drawWorld(){
 ctx.fillStyle='#182923';ctx.fillRect(0,0,W,H);
 // subtle neighborhood ground color bands
 for(let y=0;y<H;y+=570)for(let x=0;x<W;x+=620){let d=districtAt(x+310,y+285);ctx.fillStyle=districts[d].bg;ctx.globalAlpha=.72;ctx.fillRect(x+70,y+70,550,500)}ctx.globalAlpha=1;
 // waterfront and dock fingers at the far east
 ctx.fillStyle='#193c42';ctx.fillRect(3125,0,75,H);ctx.fillStyle='#52736c';ctx.fillRect(3090,0,35,H);
 for(let y=80;y<H;y+=215){ctx.fillStyle='#756348';ctx.fillRect(3098,y,100,14);ctx.fillStyle='#9b8359';ctx.fillRect(3150,y-18,18,50)}
 // roads with concrete sidewalks, asphalt and center lines
 roadsX.forEach((x,i)=>{const w=(i===0||i===roadsX.length-1)?130:142;ctx.fillStyle='#7e8071';ctx.fillRect(x-w/2,0,w,H);ctx.fillStyle='#343b3b';ctx.fillRect(x-w/2+20,0,w-40,H);ctx.fillStyle='#f0c97444';for(let y=0;y<H;y+=64)ctx.fillRect(x-2,y,4,30);
  for(let y=0;y<H;y+=28){ctx.fillStyle='#ddd0ad55';ctx.fillRect(x-w/2+5,y,7,13);ctx.fillRect(x+w/2-12,y+14,7,13)}
 });
 roadsY.forEach((y,i)=>{const w=(i===0||i===roadsY.length-1)?130:142;ctx.fillStyle='#7e8071';ctx.fillRect(0,y-w/2,W,w);ctx.fillStyle='#343b3b';ctx.fillRect(0,y-w/2+20,W,w-40);ctx.fillStyle='#f0c97444';for(let x=0;x<W;x+=64)ctx.fillRect(x,y-2,30,4);
  for(let x=0;x<W;x+=28){ctx.fillStyle='#ddd0ad55';ctx.fillRect(x,y-w/2+5,13,7);ctx.fillRect(x+14,y+w/2-12,13,7)}
 });
 // road junction markings, manholes and crosswalks
 roadsX.forEach(x=>roadsY.forEach(y=>{ctx.fillStyle='#d9d4bd66';for(let i=-4;i<=4;i++){ctx.fillRect(x+i*11-3,y-65,6,20);ctx.fillRect(x+i*11-3,y+45,6,20);ctx.fillRect(x-65,y+i*11-3,20,6);ctx.fillRect(x+45,y+i*11-3,20,6)}ctx.fillStyle='#737976';ctx.beginPath();ctx.arc(x+37,y+34,8,0,7);ctx.fill()}));
 // blocks, lots, roofs and tiny lights
 for(const b of buildings){if(b.x<camera.x-vw*.8||b.x>camera.x+vw*.8||b.y<camera.y-vh*.8||b.y>camera.y+vh*.8)continue;
  if(b.park){ctx.fillStyle='#416145';ctx.fillRect(b.x,b.y,b.w,b.h);ctx.fillStyle='#87916c';ctx.fillRect(b.x+b.w*.45,b.y,8,b.h);for(let n=0;n<6;n++){const tx=b.x+20+(n*47)%Math.max(30,b.w-30),ty=b.y+25+(n*63)%Math.max(30,b.h-30);ctx.fillStyle='#264b38';ctx.beginPath();ctx.arc(tx,ty,13,0,7);ctx.fill();ctx.fillStyle='#658557';ctx.beginPath();ctx.arc(tx-3,ty-3,9,0,7);ctx.fill()}continue}
  ctx.fillStyle='#11191888';ctx.fillRect(b.x+7,b.y+11,b.w,b.h);ctx.fillStyle='#252d2b';ctx.fillRect(b.x-5,b.y-5,b.w+10,b.h+10);ctx.fillStyle=b.roof;ctx.fillRect(b.x,b.y,b.w,b.h);
  ctx.fillStyle='#ffffff0a';ctx.fillRect(b.x+4,b.y+4,b.w-8,5);ctx.fillStyle='#101b1b66';ctx.fillRect(b.x+8,b.y+b.h-15,b.w-16,8);
  if(b.kind==='factory'){ctx.fillStyle='#a59b83';ctx.fillRect(b.x+b.w*.7,b.y-25,30,35);ctx.fillStyle='#b8a989';ctx.fillRect(b.x+b.w*.22,b.y+b.h*.4,b.w*.46,9)}
  if(b.kind==='tower'){ctx.fillStyle='#a9b69b';for(let xx=b.x+12;xx<b.x+b.w-10;xx+=25)for(let yy=b.y+18;yy<b.y+b.h-12;yy+=24)ctx.fillRect(xx,yy,7,10)}
  if(b.kind==='shop'||b.kind==='club'||b.name){ctx.fillStyle=b.d===4?'#e98e66':'#e5c775';ctx.fillRect(b.x+b.w*.2,b.y+b.h-11,b.w*.6,5);ctx.fillStyle='#f6dc93';for(let i=0;i<Math.min(4,Math.floor(b.w/45));i++)ctx.fillRect(b.x+14+i*36,b.y+b.h-26,15,12)}
  if(b.name){ctx.fillStyle='#0c1617cc';rr(b.x+b.w*.15,b.y+b.h*.38,b.w*.7,24,4,'#101819cc');ctx.fillStyle='#e6d8a8';ctx.font='bold 9px system-ui';ctx.textAlign='center';ctx.fillText(b.name,b.x+b.w*.5,b.y+b.h*.38+16)}
  ctx.strokeStyle='#ffffff12';ctx.strokeRect(b.x,b.y,b.w,b.h);
 }
 // street lamps
 for(let x=230;x<W;x+=620)for(let y=220;y<H;y+=570){ctx.fillStyle='#d8c28c';ctx.fillRect(x,y,5,5);ctx.fillStyle='#f5cb6b20';ctx.beginPath();ctx.arc(x,y,34,0,7);ctx.fill()}
}
function drawCar(c){ctx.save();ctx.translate(c.x,c.y);ctx.rotate(c.angle);const w=c.type==='van'?43:36,h=c.type==='van'?22:19;
 ctx.fillStyle='#0007';ctx.beginPath();ctx.ellipse(1,4,w*.63,h*.8,0,0,7);ctx.fill();rr(-w/2,-h/2,w,h,5,c.color);rr(-w*.1,-h*.36,w*.4,h*.72,3,'#23393b');ctx.fillStyle='#b8d2c955';ctx.fillRect(w*.08,-h*.31,w*.24,h*.62);ctx.fillStyle='#262c2b';ctx.fillRect(-w*.42,-h*.46,9,4);ctx.fillRect(w*.27,-h*.46,8,4);ctx.fillStyle='#f4dd9c';ctx.fillRect(w*.43,-h*.3,3,5);ctx.fillRect(w*.43,h*.08,3,5);if(c===player.car){ctx.strokeStyle='#e9ff99';ctx.lineWidth=2;ctx.strokeRect(-w/2-2,-h/2-2,w+4,h+4)}ctx.restore()}
function drawActor(a,isPlayer=false){ctx.save();ctx.translate(a.x,a.y);ctx.rotate(a.angle||0);ctx.fillStyle='#0008';ctx.beginPath();ctx.ellipse(2,7,10,5,0,0,7);ctx.fill();ctx.fillStyle=isPlayer?'#d9ff72':a.color;ctx.beginPath();ctx.arc(0,0,isPlayer?10:8,0,7);ctx.fill();ctx.fillStyle=isPlayer?'#f2d5a5':'#e9c49c';ctx.beginPath();ctx.arc(3,-2,4,0,7);ctx.fill();if(isPlayer){ctx.fillStyle='#263637';ctx.fillRect(4,-3,9,4)}ctx.restore()}

